// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 addAmt1, uint256 addAmt2) internal {
        addAmt1 = bound(addAmt1, 0, 1000000000000000000000000000000);
        addAmt2 = bound(addAmt2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= addAmt1 + addAmt2);
        uint256 before_balance_record;
        try c.getBalance(address(this)) returns (uint256 __r) { before_balance_record = __r; } catch { return; }
        uint before_contract_balance = address(c).balance;
        try c.addToBalance{value: addAmt1}() {} catch { return; }
        uint256 mid_balance_record;
        try c.getBalance(address(this)) returns (uint256 __r) { mid_balance_record = __r; } catch { return; }
        uint mid_contract_balance = address(c).balance;
        try c.addToBalance{value: addAmt2}() {} catch { return; }
        uint256 after_balance_record;
        try c.getBalance(address(this)) returns (uint256 __r) { after_balance_record = __r; } catch { return; }
        uint after_contract_balance = address(c).balance;
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 final_record_balance;
        try c.getBalance(address(this)) returns (uint256 __r) { final_record_balance = __r; } catch { return; }
        uint final_contract_balance = address(c).balance;
        assertTrue(mid_balance_record == before_balance_record + addAmt1
            && mid_contract_balance == before_contract_balance + addAmt1
            // check second add effect
            && after_balance_record == mid_balance_record + addAmt2
            && after_contract_balance == mid_contract_balance + addAmt2
            // check withdraw outcome correlates with revert flag
            && (
                (!reverted
                    && final_record_balance == 0
                    && final_contract_balance + (after_balance_record) == after_contract_balance)
                || (reverted
                    && final_record_balance == after_balance_record
                    && final_contract_balance == after_contract_balance)
               ));
    }

    function testFuzz_run(uint256 addAmt1, uint256 addAmt2) public {
        _run(addAmt1, addAmt2);
    }

    receive() external payable { }
}
